28	// OptionFunc is a function that configures the process.
29	type OptionFunc func(*options)
30	
31	// options contains the options for running helm in integration tests.
32	type options struct {
33		setValues []string
34	
35		// list of resources to show only
36		showOnly []string
37	
38		namespace *string
39	}
40	
41	func WithValues(values ...string) OptionFunc {
42		return func(o *options) {
43			o.setValues = append(o.setValues, values...)
44		}
45	}
46	
47	func WithGlobalValues(values ...string) OptionFunc {
48		return func(o *options) {
49			for _, v := range values {
50				o.setValues = append(o.setValues, "global."+v)
51			}
52		}
53	}
54	
55	func WithShowOnlySchedulerSTS() OptionFunc {
56		return func(o *options) {
57			o.showOnly = append(o.showOnly, "charts/dapr_scheduler/templates/dapr_scheduler_statefulset.yaml")
58		}
59	}
60	
61	func WithShowOnlySentryDeployment() OptionFunc {
62		return func(o *options) {
63			o.showOnly = append(o.showOnly, "charts/dapr_sentry/templates/dapr_sentry_deployment.yaml")
64		}
65	}
66	
67	func WithShowOnlyServices(t *testing.T) OptionFunc {
68		return func(o *options) {
69			require.NoError(t, filepath.Walk(
70				filepath.Join(binary.RootDir(t), "charts/dapr/charts"),
71				func(path string, info os.FileInfo, err error) error {
72					if err != nil {
73						return err
74					}
75					if info.IsDir() {
76						return nil
77					}
78	
79					if strings.HasSuffix(path, "service.yaml") {
80						chartPath := filepath.Join(binary.RootDir(t), "/charts/dapr")
81						relativePath, err := filepath.Rel(chartPath, path)
82						if err != nil {
83							return err
84						}
85						o.showOnly = append(o.showOnly, relativePath)
86					}
87					return nil
88				},
89			))
90		}
91	}
92	
93	// WithShowOnly adds a specific template yaml file at a specific chart to the list of resources to show only
94	func WithShowOnly(chart, tplYamlFileName string) OptionFunc {
95		return func(o *options) {
96			if !strings.HasSuffix(tplYamlFileName, ".yaml") {
97				tplYamlFileName += ".yaml"
98			}
99			o.showOnly = append(o.showOnly, fmt.Sprintf("%s/templates/%s", chart, tplYamlFileName))
100		}
101	}
102	
103	func WithNamespace(namespace string) OptionFunc {
104		return func(o *options) {
105			o.namespace = &namespace
106		}
107	}
